const tabId = 248688717;

// Let's inspect menuitem "Investing by J.P. Morgan" and "Education & goals"
// Or we can query DOM links in the page
const links = await browserjs(tabId, () => {
  return Array.from(document.querySelectorAll('a, button, [role="menuitem"]'))
    .map(el => ({
      text: el.textContent?.trim().replace(/\s+/g, ' '),
      href: el.getAttribute('href'),
      role: el.getAttribute('role'),
      ariaLabel: el.getAttribute('aria-label'),
      id: el.id
    }))
    .filter(x => x.text && (
      x.text.toLowerCase().includes('retire') || 
      x.text.toLowerCase().includes('invest') || 
      x.text.toLowerCase().includes('calculator') ||
      x.text.toLowerCase().includes('401') ||
      x.text.toLowerCase().includes('education') ||
      x.text.toLowerCase().includes('goal')
    ));
});

console.log("Matching links/elements:", JSON.stringify(links, null, 2));

